def _nombres_declarados_en_la_propuesta(propuesta):
    """Devuelve el conjunto de nombres que la propuesta DECLARA dentro de su propio codigo.

    Un nombre esta declarado si aparece como 'def <nombre>', 'class <nombre>' o como una
    asignacion de constante '<nombre> =' en el texto que la propuesta trae (codigo,
    texto_nuevo o los elementos de cambios). Un nombre declarado aqui NO es invento: es la
    reparacion haciendo su trabajo. Inventar es usar algo que no existe en ninguna parte y
    que la propuesta tampoco crea.
    """
    if not isinstance(propuesta, dict):
        return set()
    trozos = []
    for clave in ("codigo", "texto_nuevo", "texto_viejo"):
        valor = propuesta.get(clave)
        if isinstance(valor, str):
            trozos.append(valor)
    cambios = propuesta.get("cambios")
    if isinstance(cambios, list):
        for elemento in cambios:
            if isinstance(elemento, dict):
                for clave in ("codigo", "texto_nuevo", "texto_viejo"):
                    valor = elemento.get(clave)
                    if isinstance(valor, str):
                        trozos.append(valor)
    texto = "\n".join(trozos)
    declarados = set()
    for renglon in texto.splitlines():
        limpio = renglon.strip()
        for prefijo in ("def ", "class "):
            if limpio.startswith(prefijo):
                resto = limpio[len(prefijo):]
                nombre = ""
                for ch in resto:
                    if ch.isalnum() or ch == "_":
                        nombre += ch
                    else:
                        break
                if nombre:
                    declarados.add(nombre)
        if "=" in limpio and not limpio.startswith("==") and not limpio.startswith("!="):
            izquierda = limpio.split("=", 1)[0].strip()
            if izquierda and all(c.isalnum() or c == "_" for c in izquierda):
                declarados.add(izquierda)
    return declarados


def _quitar_inventos_falsos(propuesta):
    """Quita de que_invento los nombres que la propuesta DECLARA en su propio codigo.

    Devuelve (cuantos_se_quitaron, quedan). Si tras quitar los falsos no queda ninguno,
    invento_algo pasa a falso. Inventar de verdad (usar algo que no existe en ninguna parte
    y que la propuesta tampoco crea) se sigue frenando igual.
    """
    if not isinstance(propuesta, dict):
        return 0, []
    if not propuesta.get("invento_algo"):
        return 0, []
    lista = propuesta.get("que_invento")
    if not isinstance(lista, list):
        return 0, []
    declarados = _nombres_declarados_en_la_propuesta(propuesta)
    quedan = []
    quitados = 0
    for nombre in lista:
        if isinstance(nombre, str) and nombre in declarados:
            quitados += 1
        else:
            quedan.append(nombre)
    propuesta["que_invento"] = quedan
    if not quedan:
        propuesta["invento_algo"] = False
    return quitados, quedan


